sys_script_include.script:
var wfProjectTaskUtils = Class.create();
wfProjectTaskUtils.prototype = {
    initialize: function() {
    },

/*@name setProjectTaskStatus
    @description updates the status
    @param {parent project record sys Id}
    @returns does not return anything*/

setProjectTaskStatus : function(parentGr){
var prjGr = new GlideRecord('pm_project_task');
prjGr.addQuery('parent',parentGr);
prjGr.addQuery('correlation_display','CMS - Path Forward Comments');
prjGr.addActiveQuery();
prjGr.query();
if(prjGr.next())
prjGr.state=7;
prjGr.update();

},


    type: 'wfProjectTaskUtils'
};
